from typing import List, Tuple, Optional
import random


class Game:
    """
    Represents the Snake game state.

    The snake starts 3 cells long with its head at (width // 2, height // 2)
    and its body extending to the left, moving right. Food is placed on a free
    cell chosen with `random.Random(seed)`.
    """

    def __init__(self, width: int, height: int, seed: int = 0):
        """
        Initializes the game board of given dimensions.

        Args:
            width: The width of the game board.
            height: The height of the game board.
            seed: Random seed for food placement.
        """
        raise NotImplementedError

    @property
    def width(self) -> int:
        """Returns the width of the game board."""
        raise NotImplementedError

    @property
    def height(self) -> int:
        """Returns the height of the game board."""
        raise NotImplementedError

    @property
    def snake(self) -> List[Tuple[int, int]]:
        """Returns the list of (x, y) tuples representing the snake's body, head first."""
        raise NotImplementedError

    @snake.setter
    def snake(self, value: List[Tuple[int, int]]) -> None:
        """Sets the snake's body positions."""
        raise NotImplementedError

    @property
    def food(self) -> Optional[Tuple[int, int]]:
        """Returns the position of the food, or None if board is full."""
        raise NotImplementedError

    @food.setter
    def food(self, value: Optional[Tuple[int, int]]) -> None:
        """Sets the food position, or None if no food."""
        raise NotImplementedError

    @property
    def score(self) -> int:
        """Returns the current score."""
        raise NotImplementedError

    @property
    def over(self) -> bool:
        """Returns True if the game is over."""
        raise NotImplementedError

    def turn(self, direction: str) -> None:
        """
        Queues a turn for the snake.

        Args:
            direction: "up", "down", "left" or "right".
        """
        raise NotImplementedError

    def tick(self) -> None:
        """
        Advances the game state by one tick.
        Applies the oldest queued turn first.
        """
        raise NotImplementedError
